/** Loop P wave-21 round 2: the facts proxy.md and en/proxy.md state, compared with the running proxy. */
public class LoopPWave21R2ProxyDocsTest {

    private final InMemoryHttpAdapter adapter = new InMemoryHttpAdapter();
    private final RecordingLogger logger = new RecordingLogger();
    private final RestApp app = RestApp.builder().httpAdapter(adapter).jsonCodec(new StubJsonCodec())
            .logger(logger).build();
    private final List<Throwable> errors = Collections.synchronizedList(new ArrayList<Throwable>());
    private final List<Closeable> closeables = new ArrayList<>();
    private boolean started;
    private int routes;

    @After
    public void tearDown() throws IOException {
        BackendClient.plainSockets = BackendClient.SYSTEM_SOCKETS;
        Thread.interrupted();
        if (started) {
            app.shutdown(2, TimeUnit.SECONDS);
        }
        for (Closeable c : closeables) {
            c.close();
        }
    }

    private static String read(String page) throws IOException {
        File root = new File(System.getProperty("user.dir")).getParentFile();
        return new String(Files.readAllBytes(new File(root, page).toPath()), StandardCharsets.UTF_8);
    }

    /** The text from {@code heading} up to the next heading of level 2 or higher. */
    private static String section(String doc, String heading) {
        int start = doc.indexOf("\n" + heading + "\n");
        assertTrue("missing " + heading, start >= 0);
        int end = doc.indexOf("\n## ", start + heading.length() + 1);
        return end < 0 ? doc.substring(start) : doc.substring(start, end);
    }

    private <T extends Closeable> T track(T c) {
        closeables.add(c);
        return c;
    }

    private String mount(Proxy proxy) {
        String path = "/m" + routes++;
        app.use(path, proxy);
        return path;
    }

    private void start() {
        app.onError((error, req, res) -> {
            errors.add(error);
            res.status(error instanceof HttpException ? ((HttpException) error).status() : 500).send("onError");
        });
        app.listen(0);
        started = true;
    }

    private ClientResponse send(ClientRequest request) throws Exception {
        return adapter.submit(request).get(20, TimeUnit.SECONDS);
    }

    private static void interruptLater(final Thread worker, final long millis) {
        Thread t = new Thread(() -> {
            try {
                Thread.sleep(millis);
            } catch (InterruptedException e) {
                return;
            }
            worker.interrupt();
        }, "lp-interrupter");
        t.setDaemon(true);
        t.start();
    }

    private static int closedPort() throws IOException {
        try (ServerSocket s = new ServerSocket(0, 1, InetAddress.getByName("127.0.0.1"))) {
            return s.getLocalPort();
        }
    }

    // FR-PROXY-018 AC-13: a retry wait interrupted after a closed 502 answers through the error flow with a plain
    // HttpException of that status, not the backend's 502; both retry sections must say so, since they only state that
    // a remaining 502 is relayed unchanged and that an interrupt stops the retries
    @Test(timeout = 30000)
    public void FR_PROXY_018_AC13_interruptedWaitAfterA502IsAnHttpExceptionTheRetrySectionsState() throws Exception {
        RawBackend backend = track(RawBackend.answering(
                "HTTP/1.1 502 X\r\nX-From-Backend: yes\r\nContent-Length: 7\r\n\r\nbackend"));
        final AtomicInteger connects = new AtomicInteger();
        BackendClient.plainSockets = () -> new Socket() {
            @Override
            public void connect(SocketAddress endpoint, int timeout) throws IOException {
                if (connects.getAndIncrement() == 0) {
                    interruptLater(Thread.currentThread(), 100);
                }
                super.connect(endpoint, timeout);
            }
        };
        String path = mount(Proxy.to(backend.url()).retries(2).retryDelay(2, TimeUnit.SECONDS));
        start();

        ClientResponse r = send(ClientRequest.of("GET", path + "/x"));

        assertEquals(502, r.status());
        assertNull("the backend 502 is not relayed", r.header("X-From-Backend"));
        assertEquals(1, errors.size());
        assertFalse(errors.get(0) instanceof ProxyException);
        assertTrue(errors.get(0) instanceof HttpException);

        for (String[] page : new String[][] {{"docs/api/proxy.md", "## 재시도"}, {"docs/api/en/proxy.md", "## Retries"}}) {
            String retries = section(read(page[0]), page[1]);
            assertTrue(page[0] + " retry section does not say that an interrupted wait after a 502 or 503 answers "
                    + "through the error flow with an HttpException of that status instead of relaying the backend "
                    + "response:\n" + retries, retries.contains("HttpException"));
        }
    }

    // OPS-DX-010 AC-10: p and p.retries(0) share one counter, p.retries(0).maxConcurrent(16) starts a new one, another
    // Proxy.to call never shares, a proxy without maxConcurrent has none
    @Test
    public void OPS_DX_010_AC10_counterSharingIsAsTheConcurrencySectionStates() {
        String url = "http://127.0.0.1:8081";
        Proxy p = Proxy.to(url).maxConcurrent(16);
        assertNotNull(p.concurrencyCounter());
        assertSame(p.concurrencyCounter(), p.retries(0).concurrencyCounter());
        assertSame(p.concurrencyCounter(), p.stripPrefix(true).requestHeader("X-A", "1").concurrencyCounter());
        assertNotSame(p.concurrencyCounter(), p.retries(0).maxConcurrent(16).concurrencyCounter());
        assertNotSame(p.concurrencyCounter(), Proxy.to(url).maxConcurrent(16).concurrencyCounter());
        assertNull(Proxy.to(url).retries(1).concurrencyCounter());
    }

    // OPS-DX-010 AC-10: a request over the limit gets 503 CONCURRENCY_LIMIT at once without a backend connection
    @Test(timeout = 30000)
    public void OPS_DX_010_AC10_overTheLimitIs503AtOnceWithoutConnecting() throws Exception {
        final AtomicInteger connects = new AtomicInteger();
        BackendClient.plainSockets = () -> new Socket() {
            @Override
            public void connect(SocketAddress endpoint, int timeout) throws IOException {
                connects.incrementAndGet();
                super.connect(endpoint, timeout);
            }
        };
        Proxy p = Proxy.to("http://127.0.0.1:" + closedPort()).maxConcurrent(1);
        assertTrue(p.concurrencyCounter().compareAndSet(0, 1)); // the one slot is held
        String path = mount(p.retries(0));
        start();
        long t0 = System.nanoTime();
        ClientResponse r = send(ClientRequest.of("GET", path + "/x"));
        long ms = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - t0);
        p.concurrencyCounter().set(0);
        assertEquals(503, r.status());
        assertSame(ProxyException.Kind.CONCURRENCY_LIMIT, ((ProxyException) errors.get(0)).kind());
        assertEquals(0, connects.get());
        assertTrue(ms + " ms", ms < 2000);
    }

    // OPS-DX-010 AC-2: every row of the option table: default, accepted range and the exception the call throws
    @Test
    public void OPS_DX_010_AC2_optionDefaultsRangesAndExceptionsAreAsTheTableStates() {
        Proxy d = Proxy.to("http://127.0.0.1:8081");
        assertEquals(TimeUnit.SECONDS.toNanos(10), d.connectTimeoutNanos());
        assertEquals(TimeUnit.SECONDS.toNanos(60), d.writeTimeoutNanos());
        assertEquals(TimeUnit.SECONDS.toNanos(60), d.readTimeoutNanos());
        assertEquals(TimeUnit.MINUTES.toNanos(5), d.totalTimeoutNanos());
        assertEquals(0, d.retries());
        assertEquals(TimeUnit.MILLISECONDS.toNanos(200), d.retryDelayNanos());
        assertFalse(d.retryUnsafeMethods());
        assertFalse(d.stripPrefix());
        assertFalse(d.preserveHost());
        assertEquals(Proxy.NO_BODY_LIMIT, d.bodyLimit());
        assertEquals(Proxy.NO_CONCURRENCY_LIMIT, d.maxConcurrent());
        assertTrue(d.rewriteLocation());
        assertNull(d.sslSocketFactory());

        for (String opt : new String[] {"connect", "write", "read", "total"}) {
            iae(() -> timeout(d, opt, 0, TimeUnit.SECONDS));
            iae(() -> timeout(d, opt, -1, TimeUnit.SECONDS));
            npe(() -> timeout(d, opt, 1, null));
            timeout(d, opt, 1, TimeUnit.NANOSECONDS);
        }
        iae(() -> d.retries(-1));
        d.retries(0);
        iae(() -> d.retryDelay(-1, TimeUnit.MILLISECONDS));
        npe(() -> d.retryDelay(1, null));
        d.retryDelay(0, TimeUnit.MILLISECONDS);
        iae(() -> d.bodyLimit(0));
        iae(() -> d.bodyLimit(1073741825L));
        d.bodyLimit(1);
        d.bodyLimit(1073741824L);
        iae(() -> d.maxConcurrent(0));
        d.maxConcurrent(1);
        npe(() -> d.sslSocketFactory(null));
        npe(() -> d.requestHeader(null, "v"));
        npe(() -> d.requestHeader("X-A", null));
        npe(() -> d.removeRequestHeader(null));
        npe(() -> d.responseHeader(null, "v"));
        npe(() -> d.responseHeader("X-A", null));
        npe(() -> d.removeResponseHeader(null));
        iae(() -> d.requestHeader("X A", "v"));
        iae(() -> d.requestHeader("X-A", "a\r\nb"));
        iae(() -> d.responseHeader("X-A", "a\nb"));

        // The managed request names the page lists, in any letter case
        List<String> managedRequest = Arrays.asList("Connection", "Keep-Alive", "Proxy-Connection", "TE",
                "Transfer-Encoding", "Upgrade", "Proxy-Authenticate", "Proxy-Authorization", "Trailer", "Host",
                "Content-Length", "Expect", "Forwarded", "X-Forwarded-For", "X-Forwarded-Proto", "X-Forwarded-Host");
        Set<String> lower = new HashSet<>();
        for (String n : managedRequest) {
            lower.add(n.toLowerCase(Locale.ROOT));
            iae(() -> d.requestHeader(n.toUpperCase(Locale.ROOT), "v"));
            iae(() -> d.removeRequestHeader(n.toLowerCase(Locale.ROOT)));
        }
        assertEquals(lower, HeaderRules.REQUEST_MANAGED);
        List<String> managedResponse = Arrays.asList("Connection", "Keep-Alive", "Proxy-Connection", "TE",
                "Transfer-Encoding", "Upgrade", "Proxy-Authenticate", "Proxy-Authorization", "Trailer",
                "Content-Length");
        Set<String> lowerResponse = new HashSet<>();
        for (String n : managedResponse) {
            lowerResponse.add(n.toLowerCase(Locale.ROOT));
            iae(() -> d.responseHeader(n, "v"));
            iae(() -> d.removeResponseHeader(n));
        }
        assertEquals(lowerResponse, HeaderRules.RESPONSE_MANAGED);
        d.responseHeader("Set-Cookie", "a=1");
        d.removeResponseHeader("Server");
    }

    private static Proxy timeout(Proxy p, String opt, long amount, TimeUnit unit) {
        switch (opt) {
            case "connect":
                return p.connectTimeout(amount, unit);
            case "write":
                return p.writeTimeout(amount, unit);
            case "read":
                return p.readTimeout(amount, unit);
            default:
                return p.totalTimeout(amount, unit);
        }
    }

    private static void iae(Runnable r) {
        try {
            r.run();
            fail("no IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
            // stated
        }
    }

    private static void npe(Runnable r) {
        try {
            r.run();
            fail("no NullPointerException");
        } catch (NullPointerException expected) {
            // stated
        }
    }

    // OPS-DX-010 AC-3: the seven kinds and their statuses, the null message
    @Test
    public void OPS_DX_010_AC3_kindsStatusesAndNullMessageAreAsTheErrorTableStates() {
        Object[][] rows = {{"CONNECT_FAILED", 502}, {"CONNECT_TIMEOUT", 504}, {"WRITE_TIMEOUT", 504},
            {"READ_TIMEOUT", 504}, {"TOTAL_TIMEOUT", 504}, {"INVALID_RESPONSE", 502}, {"CONCURRENCY_LIMIT", 503}};
        assertEquals(rows.length, ProxyException.Kind.values().length);
        for (Object[] row : rows) {
            ProxyException e = new ProxyException(ProxyException.Kind.valueOf((String) row[0]),
                    new IOException("backend.example:8081"));
            assertEquals(row[0].toString(), row[1], e.status());
            assertNull(e.getMessage());
            assertTrue(e instanceof HttpException);
        }
    }

    // OPS-DX-010 AC-3: without onError the default page of a CONNECT_FAILED to an unresolvable host does not reveal
    // the host, and nothing is written to the app logger for that failure before the response
    @Test(timeout = 30000)
    public void OPS_DX_010_AC3_defaultPageConcealsTheTargetAndNothingIsLogged() throws Exception {
        String host = "lp-wave21-nohost.invalid";
        app.use("/x", Proxy.to("http://" + host + ":8081"));
        app.listen(0);
        started = true;
        ClientResponse r = send(ClientRequest.of("GET", "/x/y"));
        assertEquals(502, r.status());
        assertFalse(r.text(), r.text().contains(host));
        assertFalse(r.text(), r.text().contains("8081"));
        assertTrue(r.text(), r.text().contains("UnknownHostException"));
        assertTrue("logger errors: " + logger.errors, logger.errors.isEmpty());
    }

    // OPS-DX-010 AC-3: a failure after the response started aborts the client connection and is logged once
    @Test(timeout = 30000)
    public void OPS_DX_010_AC3_failureAfterTheResponseStartedIsLoggedOnceAndAborts() throws Exception {
        RawBackend backend = track(RawBackend.answering("HTTP/1.1 200 X\r\nContent-Length: 100\r\n\r\n0123456789"));
        String path = mount(Proxy.to(backend.url()));
        start();
        ClientResponse r = send(ClientRequest.of("GET", path + "/x"));
        assertEquals(200, r.status());
        assertTrue("aborted", r.abnormallyClosed());
        long deadline = System.currentTimeMillis() + 5000;
        while (logger.errors.isEmpty() && System.currentTimeMillis() < deadline) {
            Thread.sleep(20);
        }
        Thread.sleep(200);
        assertEquals("logged errors: " + logger.errors, 1, logger.errors.size());
        assertTrue(logger.errors.get(0) instanceof ProxyException);
        assertTrue("onError is not called: " + errors, errors.isEmpty());
    }

    // OPS-DX-010 AC-5: X-Forwarded-For is the socket address alone for an untrusted peer and the received values
    // followed by the socket address for a trusted one; the other forwarding headers follow the table
    @Test(timeout = 30000)
    public void OPS_DX_010_AC5_forwardingHeadersAreAsTheTableStates() throws Exception {
        RawBackend backend = track(RawBackend.answering(RawBackend.response(200, "ok")));
        String path = mount(Proxy.to(backend.url()));
        start();
        send(ClientRequest.of("GET", path + "/x").header("Host", "front.example").header("X-Forwarded-For", "6.6.6.6")
                .header("X-Forwarded-Proto", "https").header("Forwarded", "for=1.1.1.1").header("X-Real-IP", "1.1.1.1")
                .header("X-Forwarded-Port", "1").header("X-Forwarded-Prefix", "/p")
                .header("X-Forwarded-Host", "evil.example"));
        RawBackend.Received got = backend.onlyRequest();
        String peer = got.headerValues("X-Forwarded-For").get(0);
        assertEquals(Collections.singletonList(peer), got.headerValues("X-Forwarded-For"));
        assertFalse(peer.contains("6.6.6.6"));
        assertEquals(Collections.singletonList("http"), got.headerValues("X-Forwarded-Proto"));
        assertEquals(Collections.singletonList("front.example"), got.headerValues("X-Forwarded-Host"));
        for (String gone : new String[] {"Forwarded", "X-Real-IP", "X-Forwarded-Port", "X-Forwarded-Prefix"}) {
            assertTrue(gone, got.headerValues(gone).isEmpty());
        }
        assertEquals(Collections.singletonList("127.0.0.1:" + backend.port()), got.headerValues("Host"));
    }

    @Test(timeout = 30000)
    public void OPS_DX_010_AC5_trustedPeerKeepsTheClientValuesBeforeTheSocketAddress() throws Exception {
        RawBackend backend = track(RawBackend.answering(RawBackend.response(200, "ok")));
        app.trustProxyHops(1);
        String path = mount(Proxy.to(backend.url()).preserveHost(true));
        start();
        send(ClientRequest.of("GET", path + "/x").header("Host", "front.example").header("X-Forwarded-For", "6.6.6.6"));
        RawBackend.Received got = backend.onlyRequest();
        List<String> xff = got.headerValues("X-Forwarded-For");
        assertEquals(1, xff.size());
        assertTrue(xff.get(0), xff.get(0).startsWith("6.6.6.6, "));
        assertEquals(Collections.singletonList("front.example"), got.headerValues("Host"));
    }

    // OPS-DX-010 AC-2: the forwarded path table (stripPrefix) and the Location table (rewriteLocation)
    @Test(timeout = 30000)
    public void OPS_DX_010_AC2_forwardedPathAndLocationTablesHold() throws Exception {
        RawBackend b1 = track(RawBackend.answering(RawBackend.response(200, "ok")));
        RawBackend b2 = track(RawBackend.answering(RawBackend.response(200, "ok")));
        RawBackend b3 = track(RawBackend.answering(RawBackend.response(200, "ok")));
        app.use("/api", Proxy.to(b1.url()));
        app.use("/bpi", Proxy.to(b2.url()).stripPrefix(true));
        app.use("/cpi", Proxy.to(b3.url() + "/v1").stripPrefix(true));
        start();
        send(ClientRequest.of("GET", "/api/orders?x=1"));
        send(ClientRequest.of("GET", "/bpi/orders?x=1"));
        send(ClientRequest.of("GET", "/cpi/orders"));
        assertEquals("GET /api/orders?x=1 HTTP/1.1", b1.onlyRequest().requestLine());
        assertEquals("GET /orders?x=1 HTTP/1.1", b2.onlyRequest().requestLine());
        assertEquals("GET /v1/orders HTTP/1.1", b3.onlyRequest().requestLine());
    }

    @Test(timeout = 30000)
    public void OPS_DX_010_AC2_locationTableRowsHold() throws Exception {
        final int[] port = new int[1];
        RawBackend b = track(RawBackend.start((index, request, out) -> {
            String loc;
            if (request.requestLine().contains("/same")) {
                loc = "http://127.0.0.1:" + port[0] + "/api/orders/x";
            } else if (request.requestLine().contains("/strip")) {
                loc = "http://127.0.0.1:" + port[0] + "/x";
            } else {
                loc = "http://other.example/x";
            }
            out.write(("HTTP/1.1 302 X\r\nLocation: " + loc + "\r\nContent-Length: 0\r\n\r\n")
                    .getBytes(StandardCharsets.ISO_8859_1));
        }));
        port[0] = b.port();
        app.use("/api/orders", Proxy.to(b.url()));
        app.use("/s/api/orders", Proxy.to(b.url()).stripPrefix(true));
        app.use("/n/api/orders", Proxy.to(b.url()).rewriteLocation(false));
        start();
        assertEquals("/api/orders/x", send(ClientRequest.of("GET", "/api/orders/same")).header("Location"));
        assertEquals("/s/api/orders/x", send(ClientRequest.of("GET", "/s/api/orders/strip")).header("Location"));
        assertEquals("http://other.example/x", send(ClientRequest.of("GET", "/api/orders/o")).header("Location"));
        assertEquals("http://127.0.0.1:" + b.port() + "/api/orders/x",
                send(ClientRequest.of("GET", "/n/api/orders/same")).header("Location"));
    }

    // OPS-DX-010 AC-7: the first timeout reached applies: read 60 s and total 1 s give TOTAL_TIMEOUT after about 1 s
    @Test(timeout = 30000)
    public void OPS_DX_010_AC7_firstTimeoutReachedApplies() throws Exception {
        final ServerSocket silent = new ServerSocket(0, 50, InetAddress.getByName("127.0.0.1"));
        track(silent);
        final List<Socket> held = Collections.synchronizedList(new ArrayList<Socket>());
        Thread acceptor = new Thread(() -> {
            try {
                while (true) {
                    held.add(silent.accept());
                }
            } catch (IOException e) {
                // closed
            }
        });
        acceptor.setDaemon(true);
        acceptor.start();
        String path = mount(Proxy.to("http://127.0.0.1:" + silent.getLocalPort())
                .readTimeout(60, TimeUnit.SECONDS).totalTimeout(1, TimeUnit.SECONDS));
        start();
        long t0 = System.nanoTime();
        ClientResponse r = send(ClientRequest.of("GET", path + "/x"));
        long ms = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - t0);
        assertEquals(504, r.status());
        assertSame(ProxyException.Kind.TOTAL_TIMEOUT, ((ProxyException) errors.get(0)).kind());
        assertTrue(ms + " ms", ms >= 900 && ms < 5000);
        for (Socket s : held) {
            s.close();
        }
    }

    // OPS-DX-010 AC-6: no Content-Type the backend did not send is added; Set-Cookie and Vary are appended so the app's
    // values stay; the first backend line of another name replaces the app's value
    @Test(timeout = 30000)
    public void OPS_DX_010_AC6_responseHeaderRelayIsAsStated() throws Exception {
        RawBackend plain = track(RawBackend.answering("HTTP/1.1 200 X\r\nContent-Length: 2\r\n\r\nok"));
        RawBackend withHeaders = track(RawBackend.answering("HTTP/1.1 200 X\r\nVary: Accept\r\nSet-Cookie: b=2\r\n"
                + "X-Tag: backend\r\nContent-Length: 2\r\n\r\nok"));
        app.use("/p", Proxy.to(plain.url()));
        app.use("/h", (req, res, next) -> {
            res.header("Vary", "Origin").header("X-Tag", "app").append("Set-Cookie", "a=1");
            next.run();
        });
        app.use("/h", Proxy.to(withHeaders.url()));
        start();
        ClientResponse r = send(ClientRequest.of("GET", "/p/x"));
        assertEquals(200, r.status());
        assertNull("headers: " + r.headers(), r.header("Content-Type"));
        ClientResponse h = send(ClientRequest.of("GET", "/h/x"));
        List<String> vary = new ArrayList<>();
        List<String> cookies = new ArrayList<>();
        List<String> tags = new ArrayList<>();
        for (java.util.Map.Entry<String, String> e : h.headers()) {
            if (e.getKey().equalsIgnoreCase("Vary")) vary.add(e.getValue());
            if (e.getKey().equalsIgnoreCase("Set-Cookie")) cookies.add(e.getValue());
            if (e.getKey().equalsIgnoreCase("X-Tag")) tags.add(e.getValue());
        }
        assertTrue("vary " + vary, String.join(",", vary).contains("Origin") && String.join(",", vary).contains("Accept"));
        assertEquals(Arrays.asList("a=1", "b=2"), cookies);
        assertEquals(Collections.singletonList("backend"), tags);
    }

    // OPS-DX-010 AC-3: a body an earlier middleware already read gets 500 without a backend connection; a chunked body
    // over bodyLimit gets 413 and onError receives an HttpException whose cause is a BodyTooLargeException
    @Test(timeout = 30000)
    public void OPS_DX_010_AC3_consumedBodyIs500AndAChunkedOverrunIs413WithItsCause() throws Exception {
        RawBackend b = track(RawBackend.answering(RawBackend.response(200, "ok")));
        app.use("/c", (req, res, next) -> {
            java.io.InputStream in = req.bodyStream();
            while (in.read() >= 0) {
                // consume
            }
            next.run();
        });
        app.use("/c", Proxy.to(b.url()));
        app.use("/l", Proxy.to(b.url()).bodyLimit(10));
        start();
        ClientResponse c = send(ClientRequest.of("POST", "/c/x").body(new byte[5]));
        assertEquals(500, c.status());
        assertEquals(0, b.requestCount());
        ClientResponse l = send(ClientRequest.of("POST", "/l/x").body(new byte[50]));
        assertEquals(413, l.status());
        Throwable last = errors.get(errors.size() - 1);
        assertTrue(String.valueOf(last), last instanceof HttpException && !(last instanceof ProxyException));
        assertTrue(String.valueOf(last.getCause()), last.getCause() instanceof com.snoworca.naruserve.BodyTooLargeException);
    }
}

