import java.io.InputStream;
import java.io.OutputStream;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.TimeUnit;
import org.junit.After;
import org.junit.Test;

/** Loop P wave-21 round 2: the adapter limit of REL-PROXY-001 AC-1 against what proxy.md states about the slot. */
public class LoopPWave21R2SocketDocsTest {

    private RestApp app;
    private ServerSocket backend;
    private final List<Socket> held = Collections.synchronizedList(new ArrayList<Socket>());

    @After
    public void tearDown() throws IOException {
        if (app != null) {
            app.shutdown(2, TimeUnit.SECONDS);
        }
        if (backend != null) {
            backend.close();
        }
        for (Socket s : held) {
            s.close();
        }
    }

    private static String read(String page) throws IOException {
        File root = new File(System.getProperty("user.dir")).getParentFile();
        return new String(Files.readAllBytes(new File(root, page).toPath()), StandardCharsets.UTF_8);
    }

    /** The one line of {@code doc} that contains {@code marker}. */
    private static String line(String doc, String marker) {
        String found = null;
        for (String l : doc.split("\n")) {
            if (l.contains(marker)) {
                assertTrue("two lines hold " + marker, found == null);
                found = l;
            }
        }
        assertTrue("no line holds " + marker, found != null);
        return found;
    }

    private static String readHead(InputStream in) throws IOException {
        ByteArrayOutputStream head = new ByteArrayOutputStream();
        int matched = 0;
        byte[] end = {'\r', '\n', '\r', '\n'};
        while (matched < 4) {
            int b = in.read();
            if (b < 0) {
                throw new EOFException("closed inside the head: " + head);
            }
            head.write(b);
            matched = b == end[matched] ? matched + 1 : (b == '\r' ? 1 : 0);
        }
        return new String(head.toByteArray(), StandardCharsets.ISO_8859_1);
    }

    // REL-PROXY-001 AC-1: a client that disconnects while the backend has gone silent mid-body is not seen by the
    // adapter, so the slot stays held until the read timeout; proxy.md and en/proxy.md say the slot is returned when
    // "the client [is] gone" and must state this limit in that bullet
    @Test(timeout = 60000)
    public void REL_PROXY_001_AC1_silentBackendMidBodyKeepsTheSlotUntilTheReadTimeoutAsThePagesMustState()
            throws Exception {
        backend = new ServerSocket(0, 50, InetAddress.getByName("127.0.0.1"));
        Thread acceptor = new Thread(() -> {
            while (!backend.isClosed()) {
                try {
                    Socket s = backend.accept();
                    held.add(s);
                    readHead(s.getInputStream());
                    OutputStream out = s.getOutputStream();
                    out.write("HTTP/1.1 200 X\r\nContent-Length: 10000000\r\n\r\n"
                            .getBytes(StandardCharsets.ISO_8859_1));
                    out.write(new byte[262144]);
                    out.flush(); // then silent, the connection held open
                } catch (IOException e) {
                    return;
                }
            }
        }, "lp-silent-backend");
        acceptor.setDaemon(true);
        acceptor.start();

        Proxy p = Proxy.to("http://127.0.0.1:" + backend.getLocalPort()).maxConcurrent(1)
                .readTimeout(4, TimeUnit.SECONDS);
        app = RestApp.builder().httpAdapter(new TinyHttpdAdapter()).jsonCodec(new StubJsonCodec())
                .logger(new RecordingLogger()).build();
        app.use("/api", p);
        int port = app.listen(0).port();

        try (Socket client = new Socket()) {
            client.connect(new InetSocketAddress("127.0.0.1", port), 5000);
            client.setSoTimeout(10_000);
            client.getOutputStream().write("GET /api/x HTTP/1.1\r\nHost: 127.0.0.1\r\n\r\n"
                    .getBytes(StandardCharsets.ISO_8859_1));
            client.getOutputStream().flush();
            String head = readHead(client.getInputStream());
            assertTrue(head, head.startsWith("HTTP/1.1 200 "));
            // Read until nothing more arrives: the relay has handed every backend byte on and waits on the silent backend.
            client.setSoTimeout(1000);
            byte[] buf = new byte[8192];
            long got = 0;
            try {
                for (int n; (n = client.getInputStream().read(buf)) > 0; ) {
                    got += n;
                }
            } catch (java.net.SocketTimeoutException quiet) {
                // the stream went quiet
            }
            assertTrue("body bytes received " + got, got > 0);
            Thread.sleep(300);
            assertEquals(1, p.concurrencyCounter().get());
            client.setSoLinger(true, 0);
        }
        long gone = System.nanoTime();
        Thread.sleep(1500);
        int afterClientGone = p.concurrencyCounter().get();
        long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(15);
        while (p.concurrencyCounter().get() != 0 && System.nanoTime() < deadline) {
            Thread.sleep(50);
        }
        long releasedAfterMs = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - gone);
        assertEquals("released in the end", 0, p.concurrencyCounter().get());

        if (afterClientGone == 1) {
            // The slot outlived the client by the read timeout; the pages must say so where they say when it returns.
            String ko = line(read("docs/api/proxy.md"), "슬롯은 모든 검사");
            String en = line(read("docs/api/en/proxy.md"), "The slot is taken");
            String why = "the slot was held " + releasedAfterMs + " ms after the client reset (read timeout 4 s); ";
            assertTrue(why + "en bullet: " + en, en.contains("timeout"));
            assertTrue(why + "ko bullet: " + ko, ko.contains("타임아웃"));
        }
    }

    /** Sends a raw GET to the TinyHttpd port and returns everything until the close, as ISO-8859-1 text. */
    private static byte[] exchange(int port, String path) throws IOException {
        try (Socket s = new Socket()) {
            s.connect(new InetSocketAddress("127.0.0.1", port), 5000);
            s.setSoTimeout(10000);
            s.getOutputStream().write(("GET " + path + " HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n")
                    .getBytes(StandardCharsets.ISO_8859_1));
            ByteArrayOutputStream all = new ByteArrayOutputStream();
            byte[] b = new byte[4096];
            try {
                for (int n; (n = s.getInputStream().read(b)) >= 0; ) {
                    all.write(b, 0, n);
                }
            } catch (java.net.SocketException reset) {
                // the end
            }
            return all.toByteArray();
        }
    }

    // OPS-DX-010 AC-6 (SEC-PROXY-004 AC-9 limit as the page states it): over TinyHttpd the client sees the adapter's
    // reason phrase and Date, not the backend's, and a backend header byte 0xE9 arrives as 0xC3 0xA9
    @Test(timeout = 60000)
    public void OPS_DX_010_AC6_dateReasonAndHeaderBytesOverTinyHttpdAreAsThePageStates() throws Exception {
        backend = new ServerSocket(0, 50, InetAddress.getByName("127.0.0.1"));
        Thread acceptor = new Thread(() -> {
            while (!backend.isClosed()) {
                try (Socket s = backend.accept()) {
                    readHead(s.getInputStream());
                    OutputStream out = s.getOutputStream();
                    out.write("HTTP/1.1 404 Nope\r\nDate: Mon, 01 Jan 2001 00:00:00 GMT\r\nX-E: caf\u00e9\r\nContent-Length: 2\r\n\r\nno"
                            .getBytes(StandardCharsets.ISO_8859_1));
                    out.flush();
                } catch (IOException e) {
                    return;
                }
            }
        }, "lp-404-backend");
        acceptor.setDaemon(true);
        acceptor.start();
        app = RestApp.builder().httpAdapter(new TinyHttpdAdapter()).jsonCodec(new StubJsonCodec())
                .logger(new RecordingLogger()).build();
        app.use("/api", Proxy.to("http://127.0.0.1:" + backend.getLocalPort()));
        int port = app.listen(0).port();
        byte[] raw = exchange(port, "/api/x");
        String text = new String(raw, StandardCharsets.ISO_8859_1);
        assertTrue(text, text.startsWith("HTTP/1.1 404 "));
        assertTrue(text, !text.startsWith("HTTP/1.1 404 Nope"));
        assertTrue(text, !text.contains("2001"));
        assertTrue(text, text.contains("X-E: caf\u00c3\u00a9\r\n"));
    }
}
